  test("copy and the swap methods, checked against Node 26.13", async () => {
    const program = [
      "const out = [];",
      "const t = (label, f) => {",
      "  try { const r = f(); out.push(label + \" => \" + (r instanceof Uint8Array ? r.toString(\"hex\") + \" \" + Buffer.isBuffer(r) : typeof r === \"object\" ? JSON.stringify(r) : String(r))); }",
      "  catch (e) { out.push(label + \" THROWS \" + e.name + \" \" + (e.code ?? \"-\") + \" \" + e.message); }",
      "};",
      "const src = () => Buffer.from(\"abcdef\");",
      "t(\"copy all\", () => { const d = Buffer.alloc(8, 0x2e); const n = src().copy(d); return n + \" \" + d.toString(); });",
      "t(\"copy target start\", () => { const d = Buffer.alloc(8, 0x2e); const n = src().copy(d, 2); return n + \" \" + d.toString(); });",
      "t(\"copy source range\", () => { const d = Buffer.alloc(8, 0x2e); const n = src().copy(d, 0, 2, 4); return n + \" \" + d.toString(); });",
      "t(\"copy source end past\", () => { const d = Buffer.alloc(8, 0x2e); const n = src().copy(d, 0, 4, 100); return n + \" \" + d.toString(); });",
      "t(\"copy truncated by target\", () => { const d = Buffer.alloc(3); const n = src().copy(d); return n + \" \" + d.toString(); });",
      "t(\"copy target start past\", () => { const d = Buffer.alloc(3); return src().copy(d, 5); });",
      "t(\"copy source start past\", () => { const d = Buffer.alloc(3); return src().copy(d, 0, 9); });",
      "t(\"copy end before start\", () => { const d = Buffer.alloc(3); return src().copy(d, 0, 4, 2); });",
      "t(\"copy negative target\", () => { const d = Buffer.alloc(3); return src().copy(d, -1); });",
      "t(\"copy negative source start\", () => { const d = Buffer.alloc(3); return src().copy(d, 0, -1); });",
      "t(\"copy overlap same buffer\", () => { const b = Buffer.from(\"abcdef\"); b.copy(b, 2, 0, 4); return b.toString(); });",
      "t(\"copy overlap reverse\", () => { const b = Buffer.from(\"abcdef\"); b.copy(b, 0, 2, 6); return b.toString(); });",
      "t(\"copy not a buffer\", () => { const d = Buffer.alloc(3); return src().copy([1, 2, 3]); });",
      "t(\"copy into Uint8Array\", () => { const d = new Uint8Array(3); const n = src().copy(d); return n + \" \" + Array.from(d); });",
      "t(\"copy shares nothing\", () => { const s = Buffer.from([1, 2]); const d = Buffer.alloc(2); s.copy(d); s[0] = 9; return d[0]; });",
      "t(\"copy fractional\", () => { const d = Buffer.alloc(8); return src().copy(d, 1.9, 0.5, 2.9) + \" \" + d.toString(\"hex\"); });",
      "t(\"copy string target start\", () => { const d = Buffer.alloc(8); return src().copy(d, \"2\"); });",
      "t(\"swap16 ok\", () => Buffer.from([1, 2, 3, 4]).swap16());",
      "t(\"swap16 odd\", () => Buffer.from([1, 2, 3]).swap16());",
      "t(\"swap32 ok\", () => Buffer.from([1, 2, 3, 4, 5, 6, 7, 8]).swap32());",
      "t(\"swap32 bad\", () => Buffer.from([1, 2]).swap32());",
      "t(\"swap64 ok\", () => Buffer.from([1, 2, 3, 4, 5, 6, 7, 8]).swap64());",
      "t(\"swap64 bad\", () => Buffer.from([1, 2, 3, 4]).swap64());",
      "t(\"swap empty\", () => Buffer.alloc(0).swap16());",
      "t(\"swap returns same\", () => { const b = Buffer.from([1, 2]); return b.swap16() === b; });",
      "t(\"swap16 on subarray\", () => { const b = Buffer.from([9, 1, 2, 3, 4]); b.subarray(1).swap16(); return b.toString(\"hex\"); });",
      "t(\"copy inf end\", () => { const d = Buffer.alloc(8); return src().copy(d, 0, 0, Infinity); });",
      "t(\"copy NaN start\", () => { const d = Buffer.alloc(8); return src().copy(d, NaN, NaN, NaN); });",
      "t(\"copy no args\", () => src().copy());",
      "t(\"copy null target\", () => src().copy(null));",
      "t(\"copy target 1 arg string\", () => { const d = Buffer.alloc(2); return src().copy(d, \"x\", \"1\"); });",
      "t(\"copy src end > len\", () => { const d = Buffer.alloc(2); return src().copy(d, 0, 5, 99); });",
      "t(\"copy target start equal length\", () => { const d = Buffer.alloc(2); return src().copy(d, 2); });",
      "t(\"copy source start == length\", () => { const d = Buffer.alloc(2); return src().copy(d, 0, 6); });",
      "t(\"copy target too big start\", () => { const d = Buffer.alloc(2); return src().copy(d, 1e20); });",
      "t(\"copy src start big\", () => { const d = Buffer.alloc(2); return src().copy(d, 0, 1e20); });",
      "t(\"copy src neg end\", () => { const d = Buffer.alloc(2); return src().copy(d, 0, 0, -1); });",
      "t(\"copy src start 1.5 end 3\", () => { const d = Buffer.alloc(8); return src().copy(d, 0, 1.5, 3); });",
      "for (const line of out) console.log(line);",
    ];
    const result = await sandbox.execute(program.join("\n"));

    expect(result.ok ? result.logs.join("\n") : result.error).toBe(
      [
      "copy all => 6 abcdef..",
      "copy target start => 6 ..abcdef",
      "copy source range => 2 cd......",
      "copy source end past => 2 ef......",
      "copy truncated by target => 3 abc",
      "copy target start past => 0",
      "copy source start past THROWS RangeError ERR_OUT_OF_RANGE The value of \"sourceStart\" is out of range. It must be >= 0 && <= 6. Received 9",
      "copy end before start => 0",
      "copy negative target THROWS RangeError ERR_OUT_OF_RANGE The value of \"targetStart\" is out of range. It must be >= 0. Received -1",
      "copy negative source start THROWS RangeError ERR_OUT_OF_RANGE The value of \"sourceStart\" is out of range. It must be >= 0 && <= 6. Received -1",
      "copy overlap same buffer => ababcd",
      "copy overlap reverse => cdefef",
      "copy not a buffer THROWS TypeError ERR_INVALID_ARG_TYPE The \"target\" argument must be an instance of Buffer or Uint8Array. Received an instance of Array",
      "copy into Uint8Array => 3 97,98,99",
      "copy shares nothing => 1",
      "copy fractional => 2 0061620000000000",
      "copy string target start => 6",
      "swap16 ok => 02010403 true",
      "swap16 odd THROWS RangeError ERR_INVALID_BUFFER_SIZE Buffer size must be a multiple of 16-bits",
      "swap32 ok => 0403020108070605 true",
      "swap32 bad THROWS RangeError ERR_INVALID_BUFFER_SIZE Buffer size must be a multiple of 32-bits",
      "swap64 ok => 0807060504030201 true",
      "swap64 bad THROWS RangeError ERR_INVALID_BUFFER_SIZE Buffer size must be a multiple of 64-bits",
      "swap empty =>  true",
      "swap returns same => true",
      "swap16 on subarray => 0902010403",
      "copy inf end => 0",
      "copy NaN start => 0",
      "copy no args THROWS TypeError ERR_INVALID_ARG_TYPE The \"target\" argument must be an instance of Buffer or Uint8Array. Received undefined",
      "copy null target THROWS TypeError ERR_INVALID_ARG_TYPE The \"target\" argument must be an instance of Buffer or Uint8Array. Received null",
      "copy target 1 arg string => 2",
      "copy src end > len => 1",
      "copy target start equal length => 0",
      "copy source start == length => 0",
      "copy target too big start => 0",
      "copy src start big THROWS RangeError ERR_OUT_OF_RANGE The value of \"sourceStart\" is out of range. It must be >= 0 && <= 6. Received 100_000_000_000_000_000_000",
      "copy src neg end THROWS RangeError ERR_OUT_OF_RANGE The value of \"sourceEnd\" is out of range. It must be >= 0. Received -1",
      "copy src start 1.5 end 3 => 2",
    ].join("\n"),
    );
  });

  test("the lowercase names of the unsigned reads and writes are the same functions", async () => {
    const program = [
      "const P = Buffer.prototype; const names = [\"Uint8\",\"Uint16LE\",\"Uint16BE\",\"Uint32LE\",\"Uint32BE\",\"BigUint64LE\",\"BigUint64BE\"];",
      "console.log(names.map(n => [typeof P[\"read\"+n], P[\"read\"+n] === P[\"read\"+n.replace(\"Uint\",\"UInt\")], typeof P[\"write\"+n], P[\"write\"+n] === P[\"write\"+n.replace(\"Uint\",\"UInt\")]].join(\",\")).join(\" \"));",
      "const b = Buffer.from([1,2,3,4,5,6,7,8]); b.writeUint16BE(0x1234, 0); b.writeUint32LE(0xdeadbeef, 2); b.writeBigUint64BE(5n, 0);",
      "console.log(b.readUint8(0), b.readUint16LE(0), b.readUint32BE(0), b.readBigUint64LE(0), b.readBigUint64BE(0), b.writeUint8(9, 7), b);",
    ];
    const result = await sandbox.execute(program.join("\n"));

    expect(result.ok ? result.logs.join("\n") : result.error).toBe(
      [
      "function,true,function,true function,true,function,true function,true,function,true function,true,function,true function,true,function,true function,true,function,true function,true,function,true",
      "0 0 0 360287970189639680n 5n 8 <Buffer 00 00 00 00 00 00 00 09>",
    ].join("\n"),
    );
  });

