      "  t(\"readIntBE(0,\" + n + \")\", () => b.readIntBE(0, n));",
      "  t(\"readIntLE(0,\" + n + \")\", () => b.readIntLE(0, n));",
      "}",
      "t(\"readUIntBE byteLength 0\", () => b.readUIntBE(0, 0));",
      "t(\"readUIntBE byteLength 7\", () => b.readUIntBE(0, 7));",
      "t(\"readUIntBE byteLength 1.5\", () => b.readUIntBE(0, 1.5));",
      "t(\"readUIntBE byteLength string\", () => b.readUIntBE(0, \"2\"));",
      "t(\"readUIntBE short\", () => b.readUIntBE(5, 3));",
      "t(\"readUIntBE no byteLength\", () => b.readUIntBE(0));",
      "t(\"readUIntBE offset undefined\", () => b.readUIntBE(undefined, 2));",
      "t(\"readUIntBE offset neg\", () => b.readUIntBE(-1, 2));",
      "t(\"readUIntBE offset 1.5\", () => b.readUIntBE(1.5, 2));",
      "const w = Buffer.alloc(8);",
      "for (const n of [1, 3, 6]) {",
